document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("header-toggle"),i=document.getElementById("nav-bar"),r=document.getElementById("main-content"),u=document.querySelector(".navbar"),n=document.querySelector(".navbar.fixed-top");if(t&&t.addEventListener("click",function(){i&&i.classList.toggle("show");r&&r.classList.toggle("shifted");u&&u.classList.toggle("shifted")}),n){var f=function(){window.scrollY>60?n.classList.add("scrolled"):n.classList.remove("scrolled")};window.addEventListener("scroll",f,{passive:!0});f()}});